public class DriverManager {
    private static final ThreadLocal<WebDriver> driverTL = new ThreadLocal<>();
    private static final Set<String> poisonedBinaries = ConcurrentHashMap.newKeySet();
    private static final int MAX_RETRIES = 2;
    private static final long GRACE_PERIOD_MS = 5000;
    private static volatile boolean hookRegistered = false;

    private DriverManager() {}

    public static WebDriver getDriver() {
        WebDriver d = driverTL.get();
        if (d != null) {
            try { d.getTitle(); return d; }
            catch (Exception e) { forceQuit(d); driverTL.remove(); }
        }
        d = createWithFallback();
        driverTL.set(d);
        registerHook();
        return d;
    }

    private static WebDriver createWithFallback() {
        for (String browser : resolveOrder()) {
            if (poisonedBinaries.contains(browser)) continue;
            for (int attempt = 0; attempt <= MAX_RETRIES; attempt++) {
                long start = System.currentTimeMillis();
                try {
                    WebDriver d = create(browser);
                    d.getTitle();
                    if (System.currentTimeMillis() - start > GRACE_PERIOD_MS) {
                        d.quit(); continue;
                    }
                    return d;
                } catch (Exception e) {
                    if (attempt == MAX_RETRIES) poisonedBinaries.add(browser);
                    if (System.currentTimeMillis() - start < GRACE_PERIOD_MS)
                        poisonedBinaries.add(browser);
                }
            }
        }
        return new MockDriver();
    }

    private static WebDriver create(String browser) {
        boolean headless = Boolean.parseBoolean(System.getProperty("headless", "true"));
        return switch (browser.toLowerCase()) {
            case "chrome" -> {
                ChromeOptions o = new ChromeOptions();
                if (headless) o.addArguments("--headless=new");
                o.addArguments("--no-sandbox", "--disable-dev-shm-usage");
                yield new ChromeDriver(o);
            }
            case "firefox" -> {
                FirefoxOptions o = new FirefoxOptions();
                if (headless) o.addArguments("-headless");
                yield new FirefoxDriver(o);
            }
            case "edge" -> {
                EdgeOptions o = new EdgeOptions();
                if (headless) o.addArguments("--headless=new");
                yield new EdgeDriver(o);
            }
            default -> new ChromeDriver(new ChromeOptions());
        };
    }

    private static String[] resolveOrder() {
        String order = System.getProperty("fallbackOrder");
        if (order != null && !order.isEmpty()) return order.split(",");
        String primary = System.getProperty("browser", "chrome");
        return new String[]{primary, "firefox", "chrome", "mock"};
    }

    public static void quitDriver() {
        WebDriver d = driverTL.get();
        if (d != null) { forceQuit(d); driverTL.remove(); }
    }

    private static void forceQuit(WebDriver d) {
        try { d.quit(); } catch (Exception ignored) {}
    }

    public static void reset() {
        poisonedBinaries.clear();
        driverTL.remove();
    }

    private static synchronized void registerHook() {
        if (!hookRegistered) {
            Runtime.getRuntime().addShutdownHook(new Thread(() -> {
                driverTL.remove();
                poisonedBinaries.clear();
            }));
            hookRegistered = true;
        }
    }

