public class ApiValidator {
    private String method, url;
    private Object body;
    private final Map<String, String> headers = new HashMap<>();
    private boolean useRetry, useCircuitBreaker;
    private int expectedStatus = 200;
    private String expectedSchema;
    private long maxResponseTimeMs = 2000;
    private final List<Predicate<Response>> customChecks = new ArrayList<>();
    private static final CircuitBreakerState cb = new CircuitBreakerState();
    private static final TokenManager tm = new TokenManager();

    private ApiValidator() {}
    public static ApiValidator given() { return new ApiValidator(); }
    public ApiValidator get(String url) { this.method = "GET"; this.url = url; return this; }
    public ApiValidator post(String url, Object body) { this.method = "POST"; this.url = url; this.body = body; return this; }
    public ApiValidator withRetry() { this.useRetry = true; return this; }
    public ApiValidator withCircuitBreaker() { this.useCircuitBreaker = true; return this; }
    public ApiValidator expectStatus(int s) { this.expectedStatus = s; return this; }
    public ApiValidator expectSchema(String s) { this.expectedSchema = s; return this; }
    public ApiValidator expectResponseTimeLessThan(long t, TimeUnit u) { this.maxResponseTimeMs = u.toMillis(t); return this; }
    public ApiValidator expect(Predicate<Response> c) { this.customChecks.add(c); return this; }

    public ValidationResult validate() {
        List<ValidationError> errors = new ArrayList<>();
        if (useCircuitBreaker && cb.isTripped()) {
            errors.add(new ValidationError("CIRCUIT_OPEN", "Open until " + Instant.ofEpochMilli(cb.getOpenedUntil())));
            return new ValidationResult(false, errors, 0, null);
        }
        long start = System.nanoTime();
        Response response;
        try { response = executeWithRetry(errors); }
        catch (Exception e) {
            errors.add(new ValidationError("REQUEST_FAILED", e.getMessage()));
            if (useCircuitBreaker) cb.recordFailure();
            return new ValidationResult(false, errors, TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start), null);
        }
        long durationMs = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
        if (response.getStatusCode() != expectedStatus)
            errors.add(new ValidationError("STATUS_MISMATCH", "Expected " + expectedStatus + " got " + response.getStatusCode()));
        if (durationMs > maxResponseTimeMs)
            errors.add(new ValidationError("SLOW_RESPONSE", durationMs + "ms > " + maxResponseTimeMs + "ms"));
        if (expectedSchema != null) {
            try { JsonSchemaValidator.matchesJsonSchema(expectedSchema).matches(response.getBody().asString()); }
            catch (Exception e) { errors.add(new ValidationError("SCHEMA_MISMATCH", e.getMessage())); }
        }
        for (var check : customChecks) {
            try { if (!check.test(response)) errors.add(new ValidationError("CUSTOM_FAILED", check.toString())); }
            catch (Exception e) { errors.add(new ValidationError("CUSTOM_ERROR", e.getMessage())); }
        }
        System.out.printf("[%s] %s %s -> %d (%dms) circuit=%s%n", Instant.now(), method, url, response.getStatusCode(), durationMs, useCircuitBreaker ? cb.getState() : "OFF");
        if (useCircuitBreaker) {
            if (!errors.isEmpty()) cb.recordFailure(); else cb.recordSuccess();
        }
        return new ValidationResult(errors.isEmpty(), errors, durationMs, response);
    }

    private Response executeWithRetry(List<ValidationError> errors) {
        int attempts = useRetry ? 4 : 1;
        for (int i = 0; i < attempts; i++) {
            try {
                headers.put("Authorization", "Bearer " + tm.getToken());
                Response r = sendRequest();
                if (r.getStatusCode() < 500) return r;
            } catch (Exception e) { if (i == attempts - 1) throw e; }
            if (i < attempts - 1) {
                long delay = TimeUnit.SECONDS.toMillis(Math.min(1000 * (1L << i), 30000));
                try { Thread.sleep(delay); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); break; }
            }
