        if (body != null) spec.body(body);
        return switch (method) { case "GET" -> spec.get(url); case "POST" -> spec.post(url); case "PUT" -> spec.put(url); case "DELETE" -> spec.delete(url); default -> throw new IllegalArgumentException(); };
    }

    public record ValidationResult(boolean passed, List<ValidationError> errors, long durationMs, Response response) {}
    public record ValidationError(String code, String message) {}

    static class CircuitBreakerState {
        private final AtomicInteger failures = new AtomicInteger();
        private final AtomicLong openedUntil = new AtomicLong();
        private final AtomicReference<String> state = new AtomicReference<>("CLOSED");
        boolean isTripped() {
            if ("OPEN".equals(state.get())) {
                if (System.currentTimeMillis() > openedUntil.get()) {
                    state.compareAndSet("OPEN", "HALF_OPEN");
                    return false;
                }
                return true;
            }
            return false;
        }
        void recordFailure() { if (failures.incrementAndGet() >= 5) { state.set("OPEN"); openedUntil.set(System.currentTimeMillis() + 30000); } }
        void recordSuccess() { if ("HALF_OPEN".equals(state.get())) state.set("CLOSED"); failures.set(0); }
        String getState() { return state.get(); }
        long getOpenedUntil() { return openedUntil.get(); }
    }

