public class DynamicElement {
    private final String elementName;
    private final Duration timeout;
    private static final ElementMemory memory = new ElementMemory();

    private DynamicElement(Builder b) { this.elementName = b.elementName; this.timeout = b.timeout; }

    public WebElement find(WebDriver driver) {
        var strategies = allStrategies();
        for (var s : memory.orderByConfidence(elementName, strategies)) {
            long start = System.nanoTime();
            try {
                WebElement el = s.resolve(driver, elementName, timeout);
                if (el != null) {
                    long ms = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
                    memory.recordSuccess(elementName, s.name(), ms);
                    log(elementName, s.name(), "SUCCESS", ms);
                    return el;
                }
            } catch (Exception e) {
                long ms = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
                memory.recordFailure(elementName, s.name());
                log(elementName, s.name(), "FAILURE", ms);
            }
        }
        throw new NoSuchElementException("Not found: " + elementName);
    }

    public void click(WebDriver d) { find(d).click(); }
    public String getText(WebDriver d) { return find(d).getText(); }
    public void sendKeys(WebDriver d, String t) { find(d).sendKeys(t); }

    public static Builder byName(String n) { return new Builder(n); }

    public static class Builder {
        private final String elementName;
        private Duration timeout = Duration.ofSeconds(10);
        Builder(String n) { this.elementName = n; }
        public Builder withTimeout(Duration t) { this.timeout = t; return this; }
        public DynamicElement build() { return new DynamicElement(this); }
    }

    public interface ResolutionStrategy {
        WebElement resolve(WebDriver d, String name, Duration timeout);
        String name();
    }

    static class ConfigFileStrategy implements ResolutionStrategy {
        private static final Map<String, By> config = new ConcurrentHashMap<>();
        static { config.put("loginButton", By.id("login-btn")); }
        public String name() { return "CONFIG"; }
        public WebElement resolve(WebDriver d, String n, Duration t) {
            By loc = config.get(n);
            return loc != null ? new WebDriverWait(d, t).until(ExpectedConditions.presenceOfElementLocated(loc)) : null;
        }
    }

    static class DataTestIdStrategy implements ResolutionStrategy {
        public String name() { return "DATA_TESTID"; }
        public WebElement resolve(WebDriver d, String n, Duration t) {
            String kebab = n.replaceAll("([a-z])([A-Z])", "$1-$2").toLowerCase();
            return new WebDriverWait(d, t).until(ExpectedConditions.presenceOfElementLocated(By.cssSelector("[data-testid='" + kebab + "']")));
        }
    }

    static class ShadowDomStrategy implements ResolutionStrategy {
        public String name() { return "SHADOW"; }
        public WebElement resolve(WebDriver d, String n, Duration t) {
            String kebab = n.replaceAll("([a-z])([A-Z])", "$1-$2").toLowerCase();
            return new WebDriverWait(d, t).until(drv -> search(drv, drv.findElement(By.tagName("html")), "[data-testid='" + kebab + "']"));
        }
        private WebElement search(WebDriver d, WebElement host, String sel) {
            try { return host.findElement(By.cssSelector(sel)); } catch (NoSuchElementException e) {}
            WebElement sr = (WebElement) ((JavascriptExecutor) d).executeScript("return arguments[0].shadowRoot", host);
            if (sr != null) { try { return sr.findElement(By.cssSelector(sel)); } catch (NoSuchElementException e) {} }
            for (WebElement child : host.findElements(By.cssSelector("*"))) {
                try { WebElement f = search(d, child, sel); if (f != null) return f; } catch (StaleElementReferenceException e) {}
            }
            return null;
        }
    }

    static class RelativeLocatorStrategy implements ResolutionStrategy {
        public String name() { return "RELATIVE"; }
        public WebElement resolve(WebDriver d, String n, Duration t) {
            try {
                WebElement form = new WebDriverWait(d, t).until(ExpectedConditions.presenceOfElementLocated(By.tagName("form")));
                return d.findElement(RelativeLocator.withTagName("input").near(form));
            } catch (Exception e) { return null; }
        }
    }

    record Score(int success, int fail, long totalMs, int consecFail, int consecSuccess) {
        double confidence() {
            int total = success + fail;
            if (total == 0) return 0.5;
            double base = (double) success / total;
            double penalty = consecFail * 0.1;
            double bonus = Math.min(consecSuccess * 0.05, 0.3);
            double speed = totalMs > 0 ? Math.min(1000.0 / (totalMs / total), 1.0) : 0.5;
            return Math.max(0, Math.min(1, base * 0.5 + (1 - penalty) * 0.25 + bonus * 0.15 + speed * 0.1));
        }
    }

    static class ElementMemory {
        private final ConcurrentHashMap<String, ConcurrentHashMap<String, Score>> mem = new ConcurrentHashMap<>();
        synchronized void recordSuccess(String el, String s, long ms) {
            mem.computeIfAbsent(el, k -> new ConcurrentHashMap<>())
                .merge(s, new Score(1, 0, ms, 0, 1), (o, n) -> new Score(o.success + 1, o.fail, o.totalMs + ms, 0, o.consecSuccess + 1));
        }
        synchronized void recordFailure(String el, String s) {
            mem.computeIfAbsent(el, k -> new ConcurrentHashMap<>())
                .merge(s, new Score(0, 1, 0, 1, 0), (o, n) -> new Score(o.success, o.fail + 1, o.totalMs, o.consecFail + 1, 0));
        }
        List<ResolutionStrategy> orderByConfidence(String el, List<ResolutionStrategy> strats) {
            var scores = mem.getOrDefault(el, new ConcurrentHashMap<>());
            return strats.stream().sorted(Comparator.comparingDouble((ResolutionStrategy s) -> scores.getOrDefault(s.name(), new Score(0, 0, 0, 0, 0)).confidence()).reversed()).toList();
        }
    }

    private static void log(String el, String s, String st, long ms) {
        System.out.printf("[%s] %-20s | %-10s | %s | %dms%n", Instant.now(), el, s, st, ms);
    }

    private static List<ResolutionStrategy> allStrategies() {
        return List.of(new ConfigFileStrategy(), new DataTestIdStrategy(), new ShadowDomStrategy(), new RelativeLocatorStrategy());
    }
}
