public class EventPipelineListener implements IInvokedMethodListener, ISuiteListener {
    private static final EventBus bus = new EventBus();

    public void onStart(ISuite s) { bus.publish(new Event(EventType.SUITE_STARTED, s.getName(), 0, "", "")); }
    public void onFinish(ISuite s) { bus.publish(new Event(EventType.SUITE_FINISHED, s.getName(), 0, "", "")); bus.shutdown(); }
    public void beforeInvocation(IInvokedMethod m, ITestResult r) {
        if (m.isTestMethod()) bus.publish(new Event(EventType.TEST_STARTED, m.getTestMethod().getMethodName(), 0, "", ""));
    }
    public void afterInvocation(IInvokedMethod m, ITestResult r) {
        if (!m.isTestMethod()) return;
        long dur = r.getEndMillis() - r.getStartMillis();
        EventType t = switch (r.getStatus()) {
            case ITestResult.SUCCESS -> EventType.TEST_PASSED;
            case ITestResult.FAILURE -> EventType.TEST_FAILED;
            case ITestResult.SKIP -> EventType.TEST_SKIPPED;
            default -> null;
        };
        if (t == null) return;
        bus.publish(new Event(t, r.getMethod().getMethodName(), dur,
            r.getThrowable() != null ? r.getThrowable().getMessage() : "",
            r.getMethod().getTestClass().getName()));
    }

    record Event(EventType type, String testName, long durationMs, String error, String className) {
        enum EventType { TEST_STARTED, TEST_PASSED, TEST_FAILED, TEST_SKIPPED, SUITE_STARTED, SUITE_FINISHED }
        static final Event POISON = new Event(null, null, 0, null, null);
        boolean isPoison() { return this == POISON; }
    }

    static class EventBus {
        final BlockingQueue<Event> queue = new LinkedBlockingQueue<>(10000);
        final List<Consumer> consumers = new ArrayList<>();
        final AtomicBoolean shutdown = new AtomicBoolean();

        EventBus() {
            consumers.add(new ConsoleLogger(queue));
            consumers.add(new ReportGen(queue));
            consumers.add(new Metrics(queue));
            consumers.forEach(Thread::start);
            Runtime.getRuntime().addShutdownHook(new Thread(this::shutdown));
        }

        void publish(Event e) {
            if (!shutdown.get()) try { queue.offer(e, 10, TimeUnit.SECONDS); } catch (InterruptedException ex) { Thread.currentThread().interrupt(); }
        }

        void shutdown() {
            if (!shutdown.compareAndSet(false, true)) return;
            long deadline = System.currentTimeMillis() + 5000;
            for (int i = 0; i < consumers.size(); i++) queue.offer(Event.POISON);
            for (Consumer c : consumers) try { c.join(Math.max(0, deadline - System.currentTimeMillis())); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            if (System.currentTimeMillis() > deadline) System.err.println("[EventBus] Forced shutdown");
        }
    }

    static abstract class Consumer extends Thread {
        final BlockingQueue<Event> queue;
        Consumer(BlockingQueue<Event> q, String name) { super(name); this.queue = q; setDaemon(true); }
        public void run() {
            long backoff = 1000;
            while (true) {
                try { consume(); backoff = 1000; }
                catch (InterruptedException e) { return; }
                catch (Exception e) {
                    System.err.println("[" + getName() + "] crashed, restart in " + backoff + "ms");
                    try { Thread.sleep(backoff); } catch (InterruptedException ie) { return; }
                    backoff = Math.min(backoff * 2, 30000);
                }
            }
        }
        abstract void consume() throws Exception;
    }

    static class ConsoleLogger extends Consumer {
        ConsoleLogger(BlockingQueue<Event> q) { super(q, "Logger"); }
        void consume() throws Exception {
            Event e = queue.take();
            if (e.isPoison()) throw new InterruptedException();
            String msg = String.format("[%s] %-15s | %s | %dms", Instant.now(), e.type(), e.testName(), e.durationMs());
            if (e.type() == EventType.TEST_FAILED) System.err.println(msg + " | " + e.error());
            else System.out.println(msg);
        }
    }

    static class ReportGen extends Consumer {
        AtomicInteger pass = new AtomicInteger(), fail = new AtomicInteger(), skip = new AtomicInteger();
        List<String> failed = Collections.synchronizedList(new ArrayList<>());
        String suite = "Unknown";
        ReportGen(BlockingQueue<Event> q) { super(q, "Reporter"); }
        void consume() throws Exception {
            Event e = queue.take();
            if (e.isPoison()) { gen(); throw new InterruptedException(); }
            switch (e.type()) {
                case SUITE_STARTED -> suite = e.testName();
                case TEST_PASSED -> pass.incrementAndGet();
                case TEST_FAILED -> { fail.incrementAndGet(); failed.add(e.testName()); }
                case TEST_SKIPPED -> skip.incrementAndGet();
                case SUITE_FINISHED -> gen();
            }
        }
        void gen() {
            try {
                String html = "<html><h1>" + suite + "</h1><p>Passed:" + pass + " Failed:" + fail + " Skipped:" + skip + "</p></html>";
                Files.writeString(Path.of("test-output/report.html"), html);
            } catch (IOException e) { System.err.println("Report failed: " + e); }
        }
    }

    static class Metrics extends Consumer {
        ConcurrentHashMap<String, M> data = new ConcurrentHashMap<>();
        List<Long> durations = Collections.synchronizedList(new ArrayList<>());
        record M(long count, long total, long fails) {}
        Metrics(BlockingQueue<Event> q) { super(q, "Metrics"); }
        void consume() throws Exception {
            Event e = queue.take();
            if (e.isPoison()) { print(); throw new InterruptedException(); }
            if (e.type() == EventType.TEST_PASSED || e.type() == EventType.TEST_FAILED) {
                data.merge(e.testName(), new M(1, e.durationMs(), e.type() == EventType.TEST_FAILED ? 1 : 0),
                    (a, b) -> new M(a.count + b.count, a.total + b.total, a.fails + b.fails));
                durations.add(e.durationMs());
            }
            if (e.type() == EventType.SUITE_FINISHED) print();
        }
        void print() {
            if (durations.isEmpty()) return;
            var sorted = durations.stream().sorted().toList();
            System.out.printf("Avg: %.0fms P95: %dms%n", durations.stream().mapToLong(l->l).average().orElse(0), sorted.get((int)(sorted.size()*0.95)));
            data.forEach((n, m) -> { if ((double)m.fails()/m.count() > 0.1) System.out.println("Flaky: " + n); });
        }
    }
}
