public class TestDataFactory {
    private static final ThreadLocal<Gen> genTL = ThreadLocal.withInitial(Gen::new);
    private static final CleanupRegistry reg = new CleanupRegistry();

    static { Runtime.getRuntime().addShutdownHook(new Thread(reg::cleanupAll)); }

    public static Map<String, Object> generate(String profile, String name) {
        Gen g = genTL.get();
        Map<String, Object> data = g.generate(profile, name);
        reg.register(g.threadId(), profile, name, data);
        return data;
    }

    public static void freeze() { genTL.get().freeze(); }
    public static void unfreeze() { genTL.get().unfreeze(); }
    public static void cleanupThread() { reg.cleanupThread(Thread.currentThread().getId()); genTL.remove(); }

    record Gen(long threadId, AtomicInteger seq, Map<String, Map<String, Object>> generated, volatile boolean frozen) {
        Gen() { this(Thread.currentThread().getId(), new AtomicInteger(), new LinkedHashMap<>(), false); }
        void freeze() { this = new Gen(threadId, seq, generated, true); }
        void unfreeze() { this = new Gen(threadId, seq, generated, false); }

        Map<String, Object> generate(String profile, String name) {
            if (frozen && generated.containsKey(name)) return generated.get(name);
            int s = seq.incrementAndGet();
            long seed = 42L ^ (threadId << 32) ^ (s << 16);
            Random rng = new Random(seed);
            Map<String, Object> data = switch (profile.toUpperCase()) {
                case "USER" -> Map.of("id", "usr_" + threadId + "_" + s, "email", "u." + threadId + "." + s + "@t.com", "username", "tu_" + threadId + "_" + s);
                case "ORDER" -> new LinkedHashMap<>(Map.of("id", "ord_" + threadId + "_" + s, "buyerEmail", "{user.email}", "total", String.format("%.2f", 10.0 + rng.nextDouble() * 990)));
                case "PRODUCT" -> Map.of("id", "prd_" + threadId + "_" + s, "sku", "SKU-" + threadId + "-" + s, "price", String.format("%.2f", 1.0 + rng.nextDouble() * 499));
                case "PAYMENT" -> new LinkedHashMap<>(Map.of("id", "pay_" + threadId + "_" + s, "amount", "{order.total}", "method", rng.nextBoolean() ? "CC" : "PP"));
                default -> throw new IllegalArgumentException();
            };
            resolveRefs(data);
            generated.put(name, Collections.unmodifiableMap(new HashMap<>(data)));
            return generated.get(name);
        }

        void resolveRefs(Map<String, Object> data) {
            for (var e : data.entrySet()) {
                if (e.getValue() instanceof String v && v.startsWith("{") && v.endsWith("}")) {
                    String[] parts = v.substring(1, v.length()-1).split("\\.", 2);
                    if (parts.length == 2 && generated.containsKey(parts[0]))
                        e.setValue(generated.get(parts[0]).get(parts[1]));
                }
            }
        }
    }

    static class CleanupRegistry {
        private final ConcurrentHashMap<Long, List<Reg>> threadRegs = new ConcurrentHashMap<>();
        private static final Map<String, Integer> ORDER = Map.of("PAYMENT", 0, "ORDER", 1, "PRODUCT", 2, "USER", 3);
        record Reg(String profile, String name, Map<String, Object> data) {}
        void register(long tid, String profile, String name, Map<String, Object> data) {
            threadRegs.computeIfAbsent(tid, k -> new CopyOnWriteArrayList<>()).add(new Reg(profile, name, data));
        }
        void cleanupThread(long tid) {
            List<Reg> regs = threadRegs.remove(tid);
            if (regs == null) return;
            regs.stream().sorted(Comparator.comparingInt(a -> ORDER.getOrDefault(a.profile(), 99)))
                .forEach(r -> { try { ApiClient.delete(r.profile(), r.name()); } catch (Exception e) { /* log */ } });
        }
        void cleanupAll() { new ArrayList<>(threadRegs.keySet()).forEach(this::cleanupThread); }
    }
}
